// The views of each set's marks, made on first use, which is thread-safe.
const PrStringView* quoteSets() {
    static const PrStringView* sets = [] {
        static PrStringView views[countOf(kQuoteSet)][4];
        for (uint32_t set = 0; set < countOf(kQuoteSet); ++set) {
            for (uint32_t mark = 0; mark < 4; ++mark)
                views[set][mark] = nameAt(kQuoteMarkBlob, kQuoteMarkAt, kQuoteSet[set][mark]);
        }
        return &views[0][0];
    }();
    return sets;
}

